function embeddedArtURL(src) {
 if (!src.startsWith("data:")) return src;
 const raw = atob(src.slice(src.indexOf(",")+1));
 return URL.createObjectURL(new Blob([Uint8Array.from(raw, c => c.charCodeAt(0))], {type: src.slice(5,src.indexOf(';'))}));
}
